<template><div v-if="images.length" class="help-screenshots"><figure v-for="image in images" :key="image.src"><el-image :src="image.src" :alt="image.alt||image.caption" :preview-src-list="images.map(item=>item.src)" :initial-index="images.indexOf(image)" :z-index="130000" preview-teleported loading="lazy" fit="contain"><template #error><span role="alert">截图暂未加载，请刷新后重试</span></template></el-image><figcaption>{{image.caption}}</figcaption></figure></div></template>
<script setup>defineProps({images:{type:Array,default:()=>[]}})</script>
<style scoped>.help-screenshots{display:grid;gap:16px;margin:20px 0}.help-screenshots figure{margin:0}.help-screenshots .el-image{display:block;border:1px solid #cbdced;border-radius:8px;background:#f5f9ff;cursor:zoom-in}.help-screenshots :deep(img){width:100%;max-height:520px;object-fit:contain}.help-screenshots figcaption{margin-top:8px;color:#526781;font-size:12px;line-height:1.8}.help-screenshots [role=alert]{display:block;padding:20px;color:#b91c1c}</style>
